package com.coffeeshop.repository;import com.coffeeshop.exception.DatabaseException;import com.coffeeshop.model.AuditModels;import javax.sql.DataSource;import java.sql.*;import java.time.LocalDate;import java.util.*;public final class JdbcAuditRepository implements AuditRepository{private final DataSource ds;public JdbcAuditRepository(DataSource d){ds=Objects.requireNonNull(d);}public List<AuditModels.Entry>find(String search,LocalDate from,LocalDate to){String q="SELECT a.audit_log_id,u.username,a.action_code,a.entity_type,a.entity_id,a.before_data,a.after_data,a.details,a.reason,a.occurred_at FROM dbo.audit_logs a LEFT JOIN dbo.users u ON u.user_id=a.user_id WHERE a.occurred_at>=? AND a.occurred_at<? AND (?='' OR a.action_code LIKE ? OR a.entity_type LIKE ? OR COALESCE(u.username,'') LIKE ? OR COALESCE(a.details,'') LIKE ?) ORDER BY a.occurred_at DESC,a.audit_log_id DESC";try(Connection c=ds.getConnection();PreparedStatement s=c.prepareStatement(q)){s.setTimestamp(1,Timestamp.valueOf(from.atStartOfDay()));s.setTimestamp(2,Timestamp.valueOf(to.plusDays(1).atStartOfDay()));s.setString(3,search);String like="%"+search+"%";for(int i=4;i<=7;i++)s.setString(i,like);try(ResultSet r=s.executeQuery()){List<AuditModels.Entry>x=new ArrayList<>();while(r.next()){Long entity=r.getObject(5,Long.class);x.add(new AuditModels.Entry(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),entity,r.getString(6),r.getString(7),r.getString(8),r.getString(9),r.getTimestamp(10).toLocalDateTime()));}return List.copyOf(x);}}catch(SQLException e){throw new DatabaseException("Unable to load audit history.",e);}}}
